#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    VAULT_V29_BINARY_ENEMY_PROVENANCE, VAULT_V29_BINARY_ENEMY_LEVEL_COSTS, VAULT_V29_BINARY_ENEMY_BY_ENEMY_STAT
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Emit vault-v29-binary-enemy-keycosts.generated.ts from the v29 SO extract.
 *
 *   node scripts/build-vault-v29-enemy-binary.mjs
 *
 * Source: extraction-core/dumps/v29.0.0-arm64/vault-enemy-keycosts-native.json
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const PACKAGE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const REPO_ROOT = path.resolve(PACKAGE_ROOT, '..', '..')
const SRC_JSON = path.join(REPO_ROOT, 'extraction-core', 'dumps', 'v29.0.0-arm64', 'vault-enemy-keycosts-native.json')
const OUT = path.join(PACKAGE_ROOT, 'src', 'data', 'generated', 'vault-v29-binary-enemy-keycosts.generated.ts')

/** VaultUpgradeData.enemyType → workbook enemy label (dump.cs VaultEnemyType order). */
const ENEMY_BY_TYPE = {
  0: 'Basic',
  1: 'Fast',
  2: 'Tank',
  3: 'Ranged',
  4: 'Boss',
  5: 'Protector',
  6: 'Vampire',
  7: 'Scatter',
  9: 'Ray',
  10: 'Saboteur',
  11: 'Commander',
  12: 'Overcharge',
}

if (!fs.existsSync(SRC_JSON)) {
  console.error(`Missing extract: ${SRC_JSON}`)
  console.error('Run: py -3 scripts/native-v29/extract-vault-config-from-assets.py')
  process.exit(1)
}

const payload = JSON.parse(fs.readFileSync(SRC_JSON, 'utf8'))
const byVaultId = {}
const byEnemyStat = {}

for (const group of payload.enemyGroups ?? []) {
  for (const up of group.upgrades ?? []) {
    const vaultId = up.vaultId
    const costs = up.keyCosts ?? []
    if (typeof vaultId !== 'number' || !costs.length) continue
    byVaultId[vaultId] = costs
    const enemy = ENEMY_BY_TYPE[up.enemyType]
    const slot = Math.floor((vaultId % 100) / 10)
    if (enemy != null && slot >= 0 && slot <= 2) {
      byEnemyStat[`${enemy}|${slot}`] = { vaultId, keyCosts: costs }
    }
  }
}

const sortedIds = Object.keys(byVaultId).map(Number).sort((a, b) => a - b)
if (sortedIds.length !== 36) {
  console.error(`Expected 36 enemy upgrades, got ${sortedIds.length}`)
  process.exit(1)
}

const body = `/**
 * GENERATED-from-binary — v29 Enemy vault keyCost overlay.
 *
 * Source: vault-enemy-keycosts-native.json (VaultConfig SO via UnityPy + DummyDll).
 * Regenerate: node scripts/build-vault-v29-enemy-binary.mjs
 *
 * Integers from VaultUpgradeData.levels[].keyCost — not workbook floats.
 */

export const VAULT_V29_BINARY_ENEMY_PROVENANCE =
  'v29.0.0-arm64 VaultConfig.enemyGroups → VaultUpgradeData.levels[].keyCost via scripts/native-v29/extract-vault-config-from-assets.py 2026-08-27'

/** VaultID → per-level key costs (30 levels each for v29 Enemy tree). */
export const VAULT_V29_BINARY_ENEMY_LEVEL_COSTS: Record<number, readonly number[]> = {
${sortedIds.map(id => `  ${id}: ${JSON.stringify(byVaultId[id])},`).join('\n')}
} as const

/** Workbook row lookup: enemy name + stat slot 0=Attack, 1=Health, 2=Special. */
export const VAULT_V29_BINARY_ENEMY_BY_ENEMY_STAT: Record<
  string,
  { readonly vaultId: number; readonly keyCosts: readonly number[] }
> = {
${Object.entries(byEnemyStat)
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([key, row]) => `  ${JSON.stringify(key)}: { vaultId: ${row.vaultId}, keyCosts: ${JSON.stringify(row.keyCosts)} },`)
  .join('\n')}
} as const
`

fs.writeFileSync(OUT, body, 'utf8')
console.log(`wrote ${path.relative(PACKAGE_ROOT, OUT)} (${sortedIds.length} vaultIds)`)
